const LESSONS = RAW.trim().split("#").filter(Boolean).map(block => {
  const [head, words] = block.split("\n=\n");
  const lines = head.trim().split("\n");
  return {
    t: lines[0].trim(),
    e: lines.slice(1).map(l => l.split("|")),
    w: words.trim().split("\n").map(l => l.split("|"))
  };
});

